mod common;

use axum::http::{Method, StatusCode};
use axum_bookclub::app;
use common::send;
use serde_json::json;

async fn make_club(router: &axum::Router, max_members: Option<u32>) -> u64 {
    let (_, body) = send(
        router,
        Method::POST,
        "/api/clubs",
        Some(json!({"name": "C", "description": "x", "max_members": max_members})),
    )
    .await;
    body["id"].as_u64().unwrap()
}

async fn make_member(router: &axum::Router, club_id: u64, name: &str) -> u64 {
    let (_, body) = send(
        router,
        Method::POST,
        &format!("/api/clubs/{club_id}/members"),
        Some(json!({"name": name, "email": format!("{name}@example.com")})),
    )
    .await;
    body["id"].as_u64().unwrap()
}

#[tokio::test]
async fn bulk_transfer_is_atomic_on_foreign_member() {
    let router = app();
    let from_club = make_club(&router, None).await;
    let to_club = make_club(&router, None).await;
    let other_club = make_club(&router, None).await;

    let member1 = make_member(&router, from_club, "Ada").await;
    let foreign_member = make_member(&router, other_club, "Bob").await;

    let (status, _) = send(
        &router,
        Method::POST,
        &format!("/api/clubs/{from_club}/members/bulk-transfer"),
        Some(json!({"to_club_id": to_club, "member_ids": [member1, foreign_member]})),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST);

    let (_, member1_body) = send(&router, Method::GET, &format!("/api/clubs/{from_club}/members"), None).await;
    assert_eq!(member1_body.as_array().unwrap().len(), 1, "member1 must remain in the source club");
}

#[tokio::test]
async fn bulk_transfer_respects_destination_capacity() {
    let router = app();
    let from_club = make_club(&router, None).await;
    let to_club = make_club(&router, Some(1)).await;

    let member1 = make_member(&router, from_club, "Ada").await;
    let member2 = make_member(&router, from_club, "Bob").await;

    let (status, _) = send(
        &router,
        Method::POST,
        &format!("/api/clubs/{from_club}/members/bulk-transfer"),
        Some(json!({"to_club_id": to_club, "member_ids": [member1, member2]})),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST);
}

