use std::sync::Arc;

use axum::extract::{Path, State};
use axum::http::StatusCode;
use axum::response::IntoResponse;
use axum::Json;
use serde::Deserialize;
use serde_json::json;

use crate::state::{AppState, Member};

#[derive(Deserialize)]
pub struct CreateMember {
    pub name: Option<String>,
    pub email: Option<String>,
}

pub async fn create_member(
    State(state): State<Arc<AppState>>,
    Path(club_id): Path<u32>,
    Json(body): Json<CreateMember>,
) -> impl IntoResponse {
    let name = body.name.unwrap_or_default().trim().to_string();
    let email = body.email.unwrap_or_default().trim().to_string();
    if name.is_empty() {
        return (StatusCode::BAD_REQUEST, Json(json!({"error": "name is required"}))).into_response();
    }
    if email.is_empty() {
        return (StatusCode::BAD_REQUEST, Json(json!({"error": "email is required"}))).into_response();
    }

    let mut store = state.store.lock().unwrap();
    if !store.clubs.contains_key(&club_id) {
        return (StatusCode::NOT_FOUND, Json(json!({"error": "club not found"}))).into_response();
    }
    let id = store.next_member_id;
    store.next_member_id += 1;
    let member = Member { id, club_id, name, email };
    store.members.insert(id, member.clone());
    (StatusCode::CREATED, Json(member)).into_response()
}

#[derive(Deserialize)]
pub struct BulkTransferMembers {
    pub to_club_id: u32,
    pub member_ids: Vec<u32>,
}

pub async fn bulk_transfer_members(
    State(state): State<Arc<AppState>>,
    Path(from_club_id): Path<u32>,
    Json(body): Json<BulkTransferMembers>,
) -> impl IntoResponse {
    if body.member_ids.is_empty() {
        return (StatusCode::BAD_REQUEST, Json(json!({"error": "member_ids must be a non-empty array"}))).into_response();
    }

    let mut store = state.store.lock().unwrap();
    if !store.clubs.contains_key(&from_club_id) {
        return (StatusCode::NOT_FOUND, Json(json!({"error": "source club not found"}))).into_response();
    }
    let to_club = match store.clubs.get(&body.to_club_id) {
        Some(c) => c.clone(),
        None => return (StatusCode::BAD_REQUEST, Json(json!({"error": "to_club_id must reference an existing club"}))).into_response(),
    };

    for member_id in &body.member_ids {
        match store.members.get(member_id) {
            Some(m) if m.club_id == from_club_id => {}
            _ => {
                return (
                    StatusCode::BAD_REQUEST,
                    Json(json!({"error": format!("member {member_id} does not belong to the source club")})),
                )
                    .into_response();
            }
        }
    }

    if let Some(max) = to_club.max_members {
        let current = store.member_count_for_club(body.to_club_id);
        let incoming = body.member_ids.len() as u32;
        if current + incoming > max {
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({"error": "transfer would exceed destination club max_members"})),
            )
                .into_response();
        }
    }

    let mut moved: Vec<Member> = Vec::with_capacity(body.member_ids.len());
    for member_id in &body.member_ids {
        let member = store.members.get_mut(member_id).unwrap();
        member.club_id = body.to_club_id;
        moved.push(member.clone());
    }
    (StatusCode::OK, Json(moved)).into_response()
}

pub async fn list_members(
    State(state): State<Arc<AppState>>,
    Path(club_id): Path<u32>,
) -> impl IntoResponse {
    let store = state.store.lock().unwrap();
    if !store.clubs.contains_key(&club_id) {
        return (StatusCode::NOT_FOUND, Json(json!({"error": "club not found"}))).into_response();
    }
    let mut members: Vec<Member> = store
        .members
        .values()
        .filter(|m| m.club_id == club_id)
        .cloned()
        .collect();
    members.sort_by_key(|m| m.id);
    (StatusCode::OK, Json(members)).into_response()
}

